const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Antarctic region (60°S to 90°S)
  const antarcticGeometry = ee.Geometry.Rectangle([-180, -90, 180, -60]);

  // 2021 ozone hole season (September-October)
  const startDate = '2021-09-01';
  const endDate = '2021-10-31';

  // Load OMI total column ozone data
  const omiCollection = ee.ImageCollection('TOMS/MERGED')
    .filterDate(startDate, endDate)
    .filterBounds(antarcticGeometry);

  const collectionSize = omiCollection.size().getInfo();
  console.log(`OMI Images in 2021 Sept-Oct: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No OMI data found. Trying alternative source...');
    // Fallback: Try AURA OMI Level 3
    const omiL3 = ee.ImageCollection('OMINRT_3')
      .filterDate(startDate, endDate)
      .filterBounds(antarcticGeometry);
    const sizeL3 = omiL3.size().getInfo();
    console.log(`OMI L3 Images: ${sizeL3}`);

    if (sizeL3 === 0) {
      console.log('C1');
      return;
    }
  }

  // Use the best available collection
  let workingCollection = collectionSize > 0 ? omiCollection : 
    ee.ImageCollection('OMINRT_3').filterDate(startDate, endDate).filterBounds(antarcticGeometry);

  // Calculate ozone hole area (TCO < 220 DU)
  const ozoneMask = workingCollection.map(function(img) {
    // Get TCO band
    const tco = img.select('ozone');
    // Create binary mask where ozone < 220 DU
    const holeArea = tco.lt(220);
    return holeArea.set('date', img.get('system:time_start'));
  });

  // Count pixels in ozone hole for each day
  const dailyCounts = ozoneMask.map(function(img) {
    const pixelCount = img.reduceRegion(
      ee.Reducer.count(),
      antarcticGeometry,
      30000  // 30km resolution for OMI-equivalent
    ).get('ozone');
    return ee.Feature(null, {
      date: img.get('date'),
      holePixels: pixelCount
    });
  });

  // Get maximum pixel count (maximum ozone hole extent)
  const maxHolePixels = dailyCounts.aggregate_max('holePixels').getInfo();
  console.log(`Max hole pixels (daily): ${maxHolePixels}`);

  if (maxHolePixels === null || maxHolePixels === undefined) {
    console.log('C3');
    return;
  }

  // Convert pixels to area: each pixel at 30km scale = 900 km²
  const pixelAreaKm2 = 30 * 30; // 900 km² per pixel at 30km resolution
  const maxHoleAreaKm2 = maxHolePixels * pixelAreaKm2 / 1000000; // convert to millions of km²

  console.log(`Max ozone hole area 2021: ${(maxHoleAreaKm2).toFixed(2)} million km²`);
  console.log(`Threshold: 18 million km²`);
  console.log(`Valid pixels detected: ${maxHolePixels}`);

  if (maxHolePixels === 0) {
    console.log('C2');
    return;
  }

  if (maxHoleAreaKm2 >= 18) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
